#if FEAT_IQM
// Bone UBO size: 128 joints * 3 vec4 rows = 6144 bytes
// Must match IQM_MAX_JOINTS (128) from iqm.h and the shader's boneMats[128*3]
#define IQM_GPU_MAX_JOINTS 128
#define IQM_BONE_UBO_SIZE (IQM_GPU_MAX_JOINTS * 3 * sizeof(vec4_t))
// The per-draw MVP (not a VS push) is appended after the bone array in the same
// set-0 UBO. std140 places mat4 mvp 16-aligned at offset IQM_BONE_UBO_SIZE (6144).
// The buffer/descriptor cover the bones + the mvp tail.
#define IQM_MVP_UBO_OFFSET IQM_BONE_UBO_SIZE
#define IQM_UBO_TOTAL_SIZE (IQM_BONE_UBO_SIZE + 64)
#endif

// Per-TU handles for the renderer sub-channels
// used in this file. rch_init covers the five subsystem-init
// banners (ribbon, beam, sprite, particle, IQM GPU skinning). The
// bulk of vk.c routes through rch_vk (qvk dispatch / validation), with HDR /
// timing / FBO / RAL-adoption clusters split out for severity targeting.
// Engine root `renderer` is floored to WARN so all inheritors are silent by
// default; open with `log renderer.<slice> info` (or `log renderer info`
// to open the whole subtree).
R_LOG_DECLARE_CHANNEL( rch_init,    "renderer.init"    );
R_LOG_DECLARE_CHANNEL( rch_vk,      "renderer.vk"      );
R_LOG_DECLARE_CHANNEL( rch_hdr,     "renderer.hdr"     );
R_LOG_DECLARE_CHANNEL( rch_timing,  "renderer.timing"  );
R_LOG_DECLARE_CHANNEL( rch_fbo,     "renderer.fbo"     );
R_LOG_DECLARE_CHANNEL( rch_ral,     "renderer.ral"     );
R_LOG_DECLARE_CHANNEL( rch_shaders, "renderer.shaders" );

// Phase 7.12 bounded leaf: semantic names for every renderer-owned RAL
// dynamic-rendering scope. The cvar is default-off; the one-frame receipt
// counts only labels the Vulkan backend actually emits.
enum {
	VK_PM_MAIN                  = 1ull << 0,
	VK_PM_POST_BLOOM            = 1ull << 1,
	VK_PM_TONEMAP               = 1ull << 2,
	VK_PM_UI                    = 1ull << 3,
	VK_PM_SCENE_DEPTH_RESUME    = 1ull << 4,
	VK_PM_FORWARDPLUS_RESUME    = 1ull << 5,
	VK_PM_SMAA_EDGES            = 1ull << 6,
	VK_PM_SMAA_BLEND            = 1ull << 7,
	VK_PM_SMAA_RESOLVE          = 1ull << 8,
	VK_PM_BLOOM_EXTRACT         = 1ull << 9,
	VK_PM_BLOOM_MIP             = 1ull << 10,
	VK_PM_SCREENMAP             = 1ull << 11,
	VK_PM_CAPTURE               = 1ull << 12,
	VK_PM_PRESENT               = 1ull << 13,
	VK_PM_CASCADE_SHADOW        = 1ull << 14,
	VK_PM_DLIGHT_SHADOW         = 1ull << 15,
	VK_PM_TEMPORAL_MAIN         = 1ull << 16,
	VK_PM_TEMPORAL_MAIN_RESUME  = 1ull << 17
};

