	vk.modules.light_shadow_frag[1][1] = SHADER_MODULE( frag_light_shadow_line_fog_bindless );
	// world-lightmap sun-shadow receiver modules [tx][cl][fog].
	vk.modules.gen_shadow_vert[1][0][0] = SHADER_MODULE( vert_tx1_shadow );
