	vk.modules.gen_ibl_vert[2][0][0] = SHADER_MODULE( vert_tx2_ibl );
	vk.modules.gen_ibl_vert[2][0][1] = SHADER_MODULE( vert_tx2_ibl_fog );
	vk.modules.gen_ibl_vert[2][1][0] = SHADER_MODULE( vert_tx2_cl_ibl );
	vk.modules.gen_ibl_vert[2][1][1] = SHADER_MODULE( vert_tx2_cl_ibl_fog );
	vk.modules.gen_ibl_frag[1][0][0] = SHADER_MODULE( frag_tx1_ibl_bindless );
	vk.modules.gen_ibl_frag[1][0][1] = SHADER_MODULE( frag_tx1_ibl_fog_bindless );
	vk.modules.gen_ibl_frag[1][1][0] = SHADER_MODULE( frag_tx1_cl_ibl_bindless );
	vk.modules.gen_ibl_frag[1][1][1] = SHADER_MODULE( frag_tx1_cl_ibl_fog_bindless );
	vk.modules.gen_ibl_frag[2][0][0] = SHADER_MODULE( frag_tx2_ibl_bindless );
	vk.modules.gen_ibl_frag[2][0][1] = SHADER_MODULE( frag_tx2_ibl_fog_bindless );
	vk.modules.gen_ibl_frag[2][1][0] = SHADER_MODULE( frag_tx2_cl_ibl_bindless );
	vk.modules.gen_ibl_frag[2][1][1] = SHADER_MODULE( frag_tx2_cl_ibl_fog_bindless );
#endif

	vk.modules.gamma_fs   = SHADER_MODULE( gamma_frag_spv );
	vk.modules.gamma_vs   = SHADER_MODULE( gamma_vert_spv );
	vk.modules.menubg_fs  = SHADER_MODULE( menubg_frag_spv );
	SET_OBJECT_NAME( vk.modules.menubg_fs, "WiredUI menubg fragment module", VK_DEBUG_REPORT_OBJECT_TYPE_SHADER_MODULE_EXT );
	vk.modules.overlay_fs = SHADER_MODULE( overlay_frag_spv );
	vk.modules.overlay_vs = SHADER_MODULE( overlay_vert_spv );
	vk.modules.tonemap_fs = SHADER_MODULE( tonemap_frag_spv );

	// variant shaders moved from gamma.frag to tonemap.frag.
	// Bit layout (TONEMAP_VAR_*) preserved; shader source/output names changed.
	memset( vk.tonemap_variant_fs, 0, sizeof( vk.tonemap_variant_fs ) );
	// Reserved bit 0 is now the diagnostic-only GTAO isolation view. It samples
	// the denoised RAL GTAO texture directly; it does not restore the retired
	// per-pixel tonemap SSAO composite.
#if FEAT_SSAO
	vk.tonemap_variant_fs[ TONEMAP_VAR_SSAO ] = SHADER_MODULE( tonemap_ao_frag_spv );
#endif
	// Normal scene variants remain BASE / CG / SUNRAYS combinations only.
#if FEAT_TONEMAP
	vk.tonemap_variant_fs[ TONEMAP_VAR_BASE ] = SHADER_MODULE( tonemap_tonemap_frag_spv );
#endif
#if FEAT_COLOR_GRADING
	vk.tonemap_variant_fs[ TONEMAP_VAR_CG ] = SHADER_MODULE( tonemap_colorgrade_frag_spv );
#endif
